solution.solution.cpp:
#include <string>

class IFlyer
{
public:
    virtual ~IFlyer() = default;
    virtual std::string fly() const = 0;
};

class ISwimmer
{
public:
    virtual ~ISwimmer() = default;
    virtual std::string swim() const = 0;
};

class Duck : public IFlyer, public ISwimmer
{
public:
    std::string fly() const override { return "flaps"; }
    std::string swim() const override { return "paddles"; }
};

std::string takeOff(const IFlyer& flyer)
{
    return "up: " + flyer.fly();
}

std::string dive(const ISwimmer& swimmer)
{
    return "down: " + swimmer.swim();
}

unitTests:
static_assert(std::is_base_of_v<IFlyer, Duck> && std::is_base_of_v<ISwimmer, Duck>);
struct Plane : IFlyer { std::string fly() const override { return "roars"; } };

TEST("a duck does both") { const Duck d{}; CHECK_EQ(takeOff(d), "up: flaps"); CHECK_EQ(dive(d), "down: paddles"); }
TEST("the functions accept anything with the ability") { CHECK_EQ(takeOff(Plane{}), "up: roars"); }

